import React from 'react';
import { BookOpen, Monitor, Home, Award } from 'lucide-react';

const facilities = [
    { title: "Central Library", icon: BookOpen, desc: "A fully automated library with diverse collection of books and journals." },
    { title: "Computer Center", icon: Monitor, desc: "Central computing facility supporting academic and administrative functions." },
    { title: "Hostels", icon: Home, desc: "Accommodation available for both boys and girls within the campus." },
    { title: "Sports & Games", icon: Award, desc: "Facilities for various indoor and outdoor sports activities." }
];

const Gallery = () => {
    return (
        <section id="facilities" className="py-16 bg-slate-50 border-t border-slate-100">
            <div className="max-w-7xl mx-auto px-6 lg:px-10">
                <div className="mb-10 text-center">
                    <h2 className="text-[1.75rem] font-display font-bold text-slate-800 mb-4 uppercase tracking-wide">Campus Facilities</h2>
                    <div className="w-16 h-1 bg-coral mx-auto"></div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                    {facilities.map((fac, idx) => (
                        <div key={idx} className="bg-white p-6 border border-slate-200 rounded shadow-sm hover:shadow-md transition-shadow flex flex-col items-center text-center">
                            <div className="w-14 h-14 bg-slate-50 rounded-full flex items-center justify-center text-coral mb-4 border border-slate-100">
                                <fac.icon size={24} strokeWidth={1.5} />
                            </div>
                            <h3 className="text-[1.1rem] font-bold text-slate-700 mb-2">{fac.title}</h3>
                            <p className="text-[0.9rem] text-slate-500 leading-relaxed">{fac.desc}</p>
                        </div>
                    ))}
                </div>
            </div>
        </section>
    );
};

export default Gallery;
